const row = $('Get Ledger Row (Assert Owner)').first().json;
const t = $('When Executed by Another Workflow').first().json;

const ref = String(row.customer_reference_number ?? '').replace(/'/g, "''");
const account = String(t.vtiger_account_id ?? '').replace(/'/g, "''");

if (!ref || !account) {
  return [{ json: {
    query: null,
    error: 'Missing customer_reference_number or vtiger_account_id'
  } }];
}

return [{
  json: {
    query: `SELECT id, salesorder_no, sostatus FROM SalesOrder WHERE vtiger_purchaseorder = '${ref}' AND account_id = '${account}';`
  }
}];

const raw = $input.first().json ?? {};

let payload = raw.body !== undefined ? raw.body : raw.data;
if (typeof payload === 'string') {
  try {
    payload = payload.trim() ? JSON.parse(payload) : null;
  } catch {
    payload = null;
  }
}

const fail = (message) => [{
  json: {
    ok: false,
    found: 'error',
    count: 0,
    so_id: null,
    so_no: null,
    so_ids: [],
    error: message
  }
}];

if (raw.error) {
  return fail(`VTiger query error: ${raw.error.message ?? raw.error}`);
}
if (raw.statusCode !== undefined && raw.statusCode !== 200) {
  return fail(`VTiger query failed with HTTP ${raw.statusCode}`);
}
if (!payload || payload.success !== true) {
  return fail(`VTiger query rejected: ${JSON.stringify(payload?.error ?? payload)}`);
}
if (!Array.isArray(payload.result)) {
  return fail('VTiger query returned no result array');
}

const rows = payload.result;
const count = rows.length;

return [{
  json: {
    ok: true,
    count,
    found: count === 0 ? 'none' : count === 1 ? 'one' : 'many',
    so_id: rows[0]?.id ?? null,
    so_no: rows[0]?.salesorder_no ?? null,
    so_ids: rows.map(r => r.id).filter(Boolean)
  }
}];

const row = $('Record Stale Payment Unknown').first().json
  ?? $('Get Ledger Row (Assert Owner)').first().json
  ?? {};
return [{ json: { outcome: 'payment_unknown', ...row } }];

const row = $('Record Duplicate SO').first().json
  ?? $('Get Ledger Row (Assert Owner)').first().json
  ?? {};
const p = $('Parse VTiger SO Lookup').first().json ?? {};
return [{ json: {
  outcome: 'duplicate_so',
  ...row,
  count: p.count ?? 0,
  so_ids: p.so_ids ?? []
} }];

const row = $('Record Lookup Unknown').first().json
  ?? $('Get Ledger Row (Assert Owner)').first().json
  ?? {};

let p = {};
try { p = $('Parse VTiger SO Lookup').first().json ?? {}; } catch {}

let q = {};
try { q = $('Build SO Query').first().json ?? {}; } catch {}

return [{ json: {
  outcome: 'lookup_unknown',
  ...row,
  error: p.error ?? q.error ?? 'stale lookup failed'
} }];
